class _MutateThenSnapshotProbe:
    """模拟锁外核验成功后、加锁前目标被并发改写（TOCTOU）。"""

    def __init__(self, engine, mutate):
        self._inner = DevDbSessionProbe(engine)
        self._mutate = mutate

    def verify(self, *, account_id, destination_id, destination_revision):
        snapshot = self._inner.verify(
            account_id=account_id,
            destination_id=destination_id,
            destination_revision=destination_revision,
        )
        if snapshot is not None:
            self._mutate()
        return snapshot
